const MAX_OPS = 128;
const Node = struct { key: i64, left: usize, right: usize, parent: usize, red: bool };
fn leftRotate(t: *[MAX_OPS + 1]Node, root: *usize, x: usize) void { const y=t[x].right;t[x].right=t[y].left;if(t[y].left!=0)t[t[y].left].parent=x;t[y].parent=t[x].parent;if(t[x].parent==0)root.*=y else if(x==t[t[x].parent].left)t[t[x].parent].left=y else t[t[x].parent].right=y;t[y].left=x;t[x].parent=y; }
fn rightRotate(t: *[MAX_OPS + 1]Node, root: *usize, y: usize) void { const x=t[y].left;t[y].left=t[x].right;if(t[x].right!=0)t[t[x].right].parent=y;t[x].parent=t[y].parent;if(t[y].parent==0)root.*=x else if(y==t[t[y].parent].right)t[t[y].parent].right=x else t[t[y].parent].left=x;t[x].right=y;t[y].parent=x; }
fn findNode(t: *const [MAX_OPS + 1]Node, root_in: usize, key: i64) usize { var root=root_in;while(root!=0 and t[root].key!=key)root=if(key<t[root].key)t[root].left else t[root].right;return root; }
fn insertNode(t: *[MAX_OPS + 1]Node, root: *usize, z_in: usize) void { var z=z_in;var y:usize=0;var x=root.*;while(x!=0){y=x;x=if(t[z].key<t[x].key)t[x].left else t[x].right;}t[z].parent=y;if(y==0)root.*=z else if(t[z].key<t[y].key)t[y].left=z else t[y].right=z;t[z].left=0;t[z].right=0;t[z].red=true;while(t[t[z].parent].red){const p=t[z].parent;const g=t[p].parent;if(p==t[g].left){y=t[g].right;if(t[y].red){t[p].red=false;t[y].red=false;t[g].red=true;z=g;}else{if(z==t[p].right){z=p;leftRotate(t,root,z);}const pp=t[z].parent;const gg=t[pp].parent;t[pp].red=false;t[gg].red=true;rightRotate(t,root,gg);}}else{y=t[g].left;if(t[y].red){t[p].red=false;t[y].red=false;t[g].red=true;z=g;}else{if(z==t[p].left){z=p;rightRotate(t,root,z);}const pp=t[z].parent;const gg=t[pp].parent;t[pp].red=false;t[gg].red=true;leftRotate(t,root,gg);}}}t[root.*].red=false; }
fn minimum(t: *const [MAX_OPS + 1]Node, start: usize) usize { var x=start;while(t[x].left!=0)x=t[x].left;return x; }
fn transplant(t: *[MAX_OPS + 1]Node, root: *usize, u: usize, v: usize) void { if(t[u].parent==0)root.*=v else if(u==t[t[u].parent].left)t[t[u].parent].left=v else t[t[u].parent].right=v;t[v].parent=t[u].parent; }
fn deleteFix(t: *[MAX_OPS + 1]Node, root: *usize, start: usize) void { var x=start;while(x!=root.* and !t[x].red){const p=t[x].parent;if(x==t[p].left){var w=t[p].right;if(t[w].red){t[w].red=false;t[p].red=true;leftRotate(t,root,p);w=t[t[x].parent].right;}if(!t[t[w].left].red and !t[t[w].right].red){t[w].red=true;x=t[x].parent;}else{if(!t[t[w].right].red){t[t[w].left].red=false;t[w].red=true;rightRotate(t,root,w);w=t[t[x].parent].right;}const pp=t[x].parent;t[w].red=t[pp].red;t[pp].red=false;t[t[w].right].red=false;leftRotate(t,root,pp);x=root.*;}}else{var w=t[p].left;if(t[w].red){t[w].red=false;t[p].red=true;rightRotate(t,root,p);w=t[t[x].parent].left;}if(!t[t[w].right].red and !t[t[w].left].red){t[w].red=true;x=t[x].parent;}else{if(!t[t[w].left].red){t[t[w].right].red=false;t[w].red=true;leftRotate(t,root,w);w=t[t[x].parent].left;}const pp=t[x].parent;t[w].red=t[pp].red;t[pp].red=false;t[t[w].left].red=false;rightRotate(t,root,pp);x=root.*;}}}t[x].red=false; }
fn deleteNode(t: *[MAX_OPS + 1]Node, root: *usize, z: usize) void { var y=z;var x:usize=0;var was_red=t[y].red;if(t[z].left==0){x=t[z].right;transplant(t,root,z,t[z].right);}else if(t[z].right==0){x=t[z].left;transplant(t,root,z,t[z].left);}else{y=minimum(t,t[z].right);was_red=t[y].red;x=t[y].right;if(t[y].parent==z)t[x].parent=y else{transplant(t,root,y,t[y].right);t[y].right=t[z].right;t[t[y].right].parent=y;}transplant(t,root,z,y);t[y].left=t[z].left;t[t[y].left].parent=y;t[y].red=t[z].red;}if(!was_red)deleteFix(t,root,x); }
fn putI64(out: [*c]u8, offset: usize, value: i64) void { const bits: u64=@bitCast(value);for(0..8)|i|out[offset+i]=@truncate(bits>>@intCast(8*i)); }
export fn red_black_tree_unique_key_ops(input: [*c]const i64, length: usize, output: [*c]u8, capacity: usize) i64 {
 if(input==null or length<1)return -1;const n64=input[0];if(n64<0 or n64>MAX_OPS or length!=1+2*@as(usize,@intCast(n64)))return -1;const n:usize=@intCast(n64);var active:[MAX_OPS]i64=@splat(0);var ac:usize=0;var sc:usize=0
 for(0..n)|i|{const op=input[1+2*i];const key=input[2+2*i];if(op<0 or op>2 or key< -2147483648 or key>2147483647)return -1;var found=MAX_OPS;for(0..ac)|j|if(active[j]==key){found=j;break;};if(op==0){if(found!=ac or ac>=MAX_OPS)return -1;active[ac]=key;ac+=1;}else if(op==1){sc+=1;}else{if(found==MAX_OPS)return -1;for(found+1..ac)|j|active[j-1]=active[j];ac-=1;}}
 var t:[MAX_OPS+1]Node=@splat(.{.key=0,.left=0,.right=0,.parent=0,.red=false});var root:usize=0;var next:usize=1;var results:[MAX_OPS]i64=@splat(0);var rc:usize=0
 for(0..n)|i|{const op=input[1+2*i];const key=input[2+2*i];if(op==0){t[next].key=key;insertNode(&t,&root,next);next+=1;}else if(op==1){results[rc]=if(findNode(&t,root,key)!=0)1 else 0;rc+=1;}else{deleteNode(&t,&root,findNode(&t,root,key));}}
 const bytes=(2+ac+sc)*8;if(output==null or capacity<bytes)return -2;putI64(output,0,@intCast(ac));var stack:[MAX_OPS]usize=@splat(0);var top:usize=0;var current=root;var out:usize=1;while(current!=0 or top>0){while(current!=0){stack[top]=current;top+=1;current=t[current].left;}top-=1;current=stack[top];putI64(output,out*8,t[current].key);out+=1;current=t[current].right;}putI64(output,out*8,@intCast(sc));out+=1;for(0..sc)|i|{putI64(output,out*8,results[i]);out+=1;}return @intCast(bytes);
}
